// fuzz_parser.cpp -- libFuzzer harness for parse_query().
//
// The fuzzer calls this function millions of times with generated byte
// strings, mutating inputs that reach new code paths. AddressSanitizer and
// UBSan turn any out-of-bounds read, overflow, or undefined behavior into an
// immediate crash with a saved reproducer file.
//
// Build and run (needs clang; ASan needs a 48-bit address space, so use
// WSL or another x86-64 Linux machine rather than the Pi):
//   clang++ -std=c++20 -g -O1 -fsanitize=fuzzer,address,undefined \
//       -I../src fuzz_parser.cpp ../src/dns_parser.cpp -o fuzz_parser
//   mkdir -p corpus && ./fuzz_parser corpus -max_total_time=600

#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <cstring>

#include "dns_parser.hpp"

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    DnsQuery q;
    ParseError err = parse_query(data, size, q);

    // Beyond "doesn't crash": check the guarantees the rest of the server
    // relies on. If any is ever false, abort() makes the fuzzer report it.
    if (err == ParseError::None) {
        if (q.question_end > size) std::abort();            // never past the input
        if (q.question_end < 17) std::abort();              // header + root name + type/class
        if (q.name.size() > 253) std::abort();              // name length limit
        for (char c : q.name) {                             // no control chars, no uppercase
            unsigned char u = static_cast<unsigned char>(c);
            if (u < 0x21 || u > 0x7E) std::abort();
            if (u >= 'A' && u <= 'Z') std::abort();
        }
    }
    return 0;
}
